/** Actual maintained native-grown forest plus the original productive apiary and native funded Master service. */
final class ForestReserveRuntime {
 static final BlockPos CENTER=ApiaryRuntime.CENTER,OAK=CENTER.offset(-5,0,4),BIRCH=CENTER.offset(5,0,-4);
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(20);var lodge=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.LUMBERJACK.buildingId())).findFirst().orElseThrow();var p=ClaimRuntimeTests.vanillaPlayer(level,lodge.owner(),lodge.ownerName());server.getPlayerList().deop(p.getGameProfile());var track=CommerceService.store(server).professions(p.getUUID()).track(Profession.LUMBERJACK);h.assertTrue(track.completedQuestIds().contains(ApiaryJobs.FOREST),"Original full native forestry/apiary/comb history is retained");
  for(var block:ConstructionFoundations.blocks(lodge))level.getChunk(lodge.origin().offset(block.offset()));p.teleportTo(level,CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);level.getChunkSource().move(p);for(int x=(CENTER.getX()-10)>>4;x<=(CENTER.getX()+10)>>4;x++)for(int z=(CENTER.getZ()-10)>>4;z<=(CENTER.getZ()+10)>>4;z++)level.getChunk(x,z);
  if(track.completedQuestIds().contains(ForestReserveInspection.FINAL)){h.runAfterDelay(40,()->guard(h,()->restore(h,p,lodge,0)));return;}
  h.assertTrue(track.xp()==3900&&track.completedQuestIds().size()==21,"Starts from21actually earned3900XP, no rank/proof injection");
  // Replace only the private supplied low glass roof with a taller native enclosure so real trees fit.
  p.setShiftKeyDown(true);for(int dy=6;dy<=11;dy++)for(int x=-9;x<=9;x++)for(int z=-9;z<=9;z++){if(Math.abs(x)!=9&&Math.abs(z)!=9)continue;var at=CENTER.offset(x,dy,z);h.assertTrue(level.getBlockState(at).isAir(),"New private upper enclosure cells remain empty");CreateDriveRuntime.place(h,p,at,new ItemStack(Items.GLASS),at.below(),Direction.UP);}for(int z=-8;z<=8;z++)for(int x=-8;x<=8;x++){var at=CENTER.offset(x,11,z);h.assertTrue(level.getBlockState(at).isAir(),"New native roof never overwrites a tree or structure");CreateDriveRuntime.place(h,p,at,new ItemStack(Items.GLASS),at.north(),Direction.SOUTH);}p.setShiftKeyDown(false);
  for(var at:BlockPos.betweenClosed(CENTER.offset(-8,5,-8),CENTER.offset(8,5,8))){h.assertTrue(level.getBlockState(at).is(Blocks.GLASS),"Only identified private QA glass scaffolding is removed");BlacksmithRepairRuntime.near(p,at);h.assertTrue(p.gameMode.destroyBlock(at),"Owner removes raw test glass through native claim-checked destruction");}
  for(int x=-3;x<=4;x++){var ground=CENTER.offset(x,-1,7);var held=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SHOVEL));use(p,ground);h.assertTrue(level.getBlockState(ground).is(Blocks.DIRT_PATH),"Native shovel creates actual connected supported path");p.setItemInHand(InteractionHand.MAIN_HAND,held);}for(var at:List.of(CENTER.offset(-6,0,6),CENTER.offset(6,0,6)))CreateDriveRuntime.place(h,p,at,new ItemStack(Items.TORCH),at.below(),Direction.UP);
  plant(h,p,OAK,Items.OAK_SAPLING);plant(h,p,BIRCH,Items.BIRCH_SAPLING);plant(h,p,CENTER.south(5),Items.SPRUCE_SAPLING);h.runAfterDelay(3,()->guard(h,()->grow(h,p,lodge,0)));
 }
 static void plant(GameTestHelper h,ServerPlayer p,BlockPos at,Item sapling){h.assertTrue(p.serverLevel().getBlockState(at).isAir(),"Native sapling site is empty");var held=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(sapling));use(p,at.below());h.assertTrue(p.getMainHandItem().isEmpty()&&p.serverLevel().getBlockState(at).getBlock() instanceof SaplingBlock,"Actual supplied native sapling placement consumes one input");p.setItemInHand(InteractionHand.MAIN_HAND,held);}
 static void use(ServerPlayer p,BlockPos clicked){BlacksmithRepairRuntime.near(p,clicked.above());p.gameMode.useItemOn(p,p.serverLevel(),p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(clicked).add(0,.5,0),Direction.UP,clicked,false));}
 static void grow(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lodge,int attempt)throws Exception{
  for(var at:List.of(OAK,BIRCH)){h.assertTrue(TreeSavedData.get(p.server).evidence().plantAt("minecraft:overworld",at).isPresent()||!(p.serverLevel().getBlockState(at).getBlock() instanceof SaplingBlock),"Native recorded planter survives before growth");if(!(p.serverLevel().getBlockState(at).getBlock() instanceof SaplingBlock))continue;var held=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BONE_MEAL,64));for(int n=0;n<64&&p.serverLevel().getBlockState(at).getBlock() instanceof SaplingBlock;n++)use(p,at);p.setItemInHand(InteractionHand.MAIN_HAND,held);h.assertTrue(!(p.serverLevel().getBlockState(at).getBlock() instanceof SaplingBlock),"Real native tree feature succeeds with paid bonemeal, not placed log/leaf fabrication");}
  p.teleportTo(p.serverLevel(),CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);p.serverLevel().getChunkSource().move(p);p.server.tickRateManager().setTickRate(200);h.runAfterDelay(20,()->guard(h,()->awaitApiary(h,p,lodge,0)));
 }
 static void awaitApiary(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lodge,int ticks)throws Exception{p.moveTo(CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5);p.serverLevel().getChunkSource().move(p);ApiaryRuntime.stepNativeHiveTime(p);try{h.assertTrue(ForestReserveInspection.validate(p,CENTER).startsWith("reserve="),"Actual native-grown species and working apiary compose the live reserve");approve(h,p,lodge);return;}catch(IllegalStateException waiting){if(ticks%400==0)com.mojang.logging.LogUtils.getLogger().info("FOREST_RESERVE_WAIT {} {}",ticks,waiting.getMessage());h.assertTrue(ticks<5400,"Actual maintained forest and native bees become ready: "+waiting.getMessage());}h.runAfterDelay(20,()->guard(h,()->awaitApiary(h,p,lodge,ticks+20)));}
 static void approve(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lodge)throws Exception{var level=p.serverLevel();var admin=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("ReserveWarden".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"ReserveWarden");p.server.getPlayerList().op(admin.getGameProfile());admin.teleportTo(level,CENTER.getX()+2.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);level.getChunkSource().move(admin);String reason="Native managed forest public paths pollinators and consent reviewed";var q=ProfessionInspectionService.review(admin,p,ForestReserveInspection.RESERVE,CENTER,reason);var top=CENTER.offset(8,10,8);h.assertTrue(level.getBlockState(top).isAir(),"High retained snapshot probe is empty");CreateDriveRuntime.place(h,p,top,new ItemStack(Items.TORCH),top.east(),Direction.WEST); // a wall torch on the actual enclosure
  attend(p,admin);boolean denied=false;try{ProfessionInspectionService.confirm(admin,q);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Still-valid upper reserve geometry changes invalidate staged confirmation");BlacksmithRepairRuntime.near(p,top);h.assertTrue(p.gameMode.destroyBlock(top),"Only new native temporary wall torch is removed");attend(p,admin);q=ProfessionInspectionService.review(admin,p,ForestReserveInspection.RESERVE,CENTER,reason);ClaimRuntimeTests.ftbUnclaim(level,CENTER);ClaimRuntimeTests.ftbClaim(admin,CENTER);denied=false;try{ProfessionInspectionService.confirm(admin,q);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Post-review FTB revocation denies reserve approval");ClaimRuntimeTests.ftbUnclaim(level,CENTER);ClaimRuntimeTests.ftbClaim(p,CENTER);attend(p,admin);q=ProfessionInspectionService.review(admin,p,ForestReserveInspection.RESERVE,CENTER,reason);ProfessionInspectionService.confirm(admin,q);h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.LUMBERJACK).xp()==4200,"Actual authored maintained reserve adds300XP once");p.server.getPlayerList().deop(admin.getGameProfile());for(var block:ConstructionFoundations.blocks(lodge))level.getChunk(lodge.origin().offset(block.offset()));BlacksmithRepairRuntime.near(p,lodge.origin().offset(BlueprintRegistry.get(lodge.blueprint(),1).home()));ProfessionPremisesRuntimeTests.whenResidents(h,List.of(lodge),()->guard(h,()->service(h,p,lodge,admin)));
 }
 static void service(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lodge,ServerPlayer admin)throws Exception{var server=p.server;var store=CommerceService.store(server);String id="kingdom_smp:lumberjack/m06";h.assertTrue(store.commissionContractPeriods(p.getUUID(),id)==0,"Old Apprentice/weekly service cannot become a Master receipt");var path=server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");CommissionQuestRules.get(server);var data=JsonParser.parseString(Files.readString(path)).getAsJsonObject();data.getAsJsonObject("goals").addProperty(id,1);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(data));CommissionQuestRules.clear(server);CreateCraftRuntime.counter(p,lodge);var terms=ContractRules.get(server).get("lumberjack/daily");h.assertTrue(p.getInventory().add(new ItemStack(terms.item(),terms.quantity())),"Private actual raw contract materials fit native inventory");int before=p.getInventory().countItem(terms.item());long pool=store.contractPoolSpent("daily",ContractRules.period("daily"));var quote=ContractService.review(p,"lumberjack/daily");ContractService.confirm(p,quote.nonce());boolean replay=false;try{ContractService.confirm(p,quote.nonce());}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&p.getInventory().countItem(terms.item())==before-terms.quantity()&&store.contractPoolSpent("daily",ContractRules.period("daily"))==pool+terms.reward()&&store.commissionContractPeriods(p.getUUID(),id)==1,"Real materials consumed and finite funded mail issued once with Master scope");var q=ProfessionService.review(p,"quest:"+id);ProfessionService.confirm(p,q.nonce());server.getPlayerList().op(admin.getGameProfile());p.teleportTo(p.serverLevel(),CENTER.getX()+.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);attend(p,admin);var finalReview=ProfessionInspectionService.review(admin,p,ForestReserveInspection.FINAL,CENTER,"Renewable native supply conservation and community service reviewed");ProfessionInspectionService.confirm(admin,finalReview);var track=store.professions(p.getUUID()).track(Profession.LUMBERJACK);h.assertTrue(track.xp()==4800&&track.completedQuestIds().size()==24&&store.professions(p.getUUID()).rank(Profession.LUMBERJACK,ProfessionService.quests())==ProfessionRank.MASTER,"Every real8A/8J/8Master objective earns4800XP/Master and purchase rights, no free equipment");server.getPlayerList().deop(admin.getGameProfile());CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("FOREST_RESERVE_NATIVE_PASSED: original21actual forestry/apiary proofs, paid native sapling/bonemeal/retained mixed forest, current productive reserve/real paths and lights, high geometry and FTB refusal, real finite funded Master service/native consumption/replay refusal, confirmed final conservation/all24earned4800XP/Master; private native machine time/raw materials and period5to1only, no profession proof/XP injection");h.succeed();}
 static void attend(ServerPlayer p,ServerPlayer admin){BlacksmithRepairRuntime.near(p,CENTER);admin.teleportTo(p.serverLevel(),CENTER.getX()+2.5,CENTER.getY(),CENTER.getZ()+.5,Set.of(),0,0);admin.serverLevel().getChunkSource().move(admin);}
 static void restore(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lodge,int waited)throws Exception{try{ForestReserveInspection.validate(p,CENTER);}catch(IllegalStateException pending){h.assertTrue(waited<400,"Saved native reserve/bee entities restore without replacement: "+pending.getMessage());h.runAfterDelay(20,()->guard(h,()->restore(h,p,lodge,waited+20)));return;}var r=CommerceService.store(p.server).professions(p.getUUID());h.assertTrue(r.track(Profession.LUMBERJACK).xp()==4800&&r.track(Profession.LUMBERJACK).completedQuestIds().size()==24&&r.rank(Profession.LUMBERJACK,ProfessionService.quests())==ProfessionRank.MASTER,"Second JVM keeps all24and actual Master rank");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("FOREST_RESERVE_RESTART_PASSED: native retained mixed forest/current productive apiary/all24earned4800XP/Master/scoped funded service receipt/original profession records survive second JVM");h.succeed();}
 interface Step{void run()throws Exception;}static void guard(GameTestHelper h,Step s){try{s.run();}catch(Exception e){com.mojang.logging.LogUtils.getLogger().error("Native forest reserve fixture failed",e);h.fail(e.toString());}}
}
